/// Full-pressure footprint width relative to the tool's, at pressure p
/// (from the footprint formula in bristle::drag_on).
fn spread(p: f32, splay: f32) -> f32 {
    (0.45 + 0.55 * p) * (1.0 + splay * (p - 0.5))
}

